// Package objects would be generated by gen:authz from package model: one
// struct per type holding exactly the facts its permissions need. Handlers fill
// them from tenant-scoped rows they loaded, never from request payloads.
package objects

import "github.com/speakeasy-api/gram/spikes/clean-slate-authz/authz"

func org(id string) authz.Ref { return authz.Ref{Type: "organization", ID: id} }

type Organization struct{ ID string }

func (o Organization) AuthzRef() authz.Ref { return org(o.ID) }

type Project struct {
	ID             string
	OrganizationID string
}

func (o Project) AuthzRef() authz.Ref {
	return authz.Ref{Type: "project", ID: o.ID, Parents: []authz.Ref{org(o.OrganizationID)}}
}

type MCPServer struct {
	ID             string
	ProjectID      string
	OrganizationID string
}

func (o MCPServer) AuthzRef() authz.Ref {
	return authz.Ref{Type: "mcp_server", ID: o.ID, Parents: []authz.Ref{{Type: "project", ID: o.ProjectID}, org(o.OrganizationID)}}
}

// User is a person as the *target* of a check (whose activity is reviewed).
type User struct {
	ID             string
	OrganizationID string
}

func (o User) AuthzRef() authz.Ref {
	return authz.Ref{Type: "user", ID: o.ID, Parents: []authz.Ref{org(o.OrganizationID)}}
}

type Agent struct {
	ID             string
	ProjectID      string
	OrganizationID string
	OwnerUserID    string // attribute "owner": agents.owner_user_id
}

func (o Agent) AuthzRef() authz.Ref {
	return authz.Ref{
		Type: "agent", ID: o.ID,
		Parents: []authz.Ref{{Type: "project", ID: o.ProjectID}, org(o.OrganizationID)},
		Attrs:   map[string][]authz.Ref{"owner": refs(User{ID: o.OwnerUserID, OrganizationID: o.OrganizationID}, o.OwnerUserID != "")},
	}
}

type Chat struct {
	ID             string
	ProjectID      string
	OrganizationID string
	AuthorUserID   string // attribute "author": chats.user_id; empty for agent-only sessions
	Agent          *Agent // attribute "agent": chats.agent_id joined to agents
}

func (o Chat) AuthzRef() authz.Ref {
	var agent []authz.Ref
	if o.Agent != nil {
		agent = []authz.Ref{o.Agent.AuthzRef()}
	}
	return authz.Ref{
		Type: "chat", ID: o.ID,
		Parents: []authz.Ref{{Type: "project", ID: o.ProjectID}, org(o.OrganizationID)},
		Attrs: map[string][]authz.Ref{
			"author": refs(User{ID: o.AuthorUserID, OrganizationID: o.OrganizationID}, o.AuthorUserID != ""),
			"agent":  agent,
		},
	}
}

func refs(o authz.Object, present bool) []authz.Ref {
	if !present {
		return []authz.Ref{}
	}
	return []authz.Ref{o.AuthzRef()}
}
